import React, { Component } from 'react'
import NewsItem from './NewsItem'

export class news extends Component {
  // articles= [
  //   // {
  //   //   "source": {
  //   //     "id": "espn-cric-info",
  //   //     "name": "ESPN Cric Info"
  //   //   },
  //   //   "author": null,
  //   //   "title": "PCB hands Umar Akmal three-year ban from all cricket | ESPNcricinfo.com",
  //   //   "description": "Penalty after the batsman pleaded guilty to not reporting corrupt approaches | ESPNcricinfo.com",
  //   //   "url": "http://www.espncricinfo.com/story/_/id/29103103/pcb-hands-umar-akmal-three-year-ban-all-cricket",
  //   //   "urlToImage": "https://a4.espncdn.com/combiner/i?img=%2Fi%2Fcricket%2Fcricinfo%2F1099495_800x450.jpg",
  //   //   "publishedAt": "2020-04-27T11:41:47Z",
  //   //   "content": "Umar Akmal's troubled cricket career has hit its biggest roadblock yet, with the PCB handing him a ban from all representative cricket for three years after he pleaded guilty of failing to report det… [+1506 chars]"
  //   // },
  //   // {
  //   //   "source": {
  //   //     "id": "espn-cric-info",
  //   //     "name": "ESPN Cric Info"
  //   //   },
  //   //   "author": null,
  //   //   "title": "What we learned from watching the 1992 World Cup final in full again | ESPNcricinfo.com",
  //   //   "description": "Wides, lbw calls, swing - plenty of things were different in white-ball cricket back then | ESPNcricinfo.com",
  //   //   "url": "http://www.espncricinfo.com/story/_/id/28970907/learned-watching-1992-world-cup-final-full-again",
  //   //   "urlToImage": "https://a4.espncdn.com/combiner/i?img=%2Fi%2Fcricket%2Fcricinfo%2F1219926_1296x729.jpg",
  //   //   "publishedAt": "2020-03-30T15:26:05Z",
  //   //   "content": "Last week, we at ESPNcricinfo did something we have been thinking of doing for eight years now: pretend-live ball-by-ball commentary for a classic cricket match. We knew the result, yes, but we tried… [+6823 chars]"
  //   // }
  // ]
  constructor(){
      super();
       console.log("hello ,i am a constructor from News component")
       this.state={
         articles:[],
         loading:false,
         page:1,

 
       }
     }
      async componentDidMount(){
        // console.log("cdm");
        let url="https://newsapi.org/v2/top-headlines?country=us&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page=1pageSize=20";
        let data= await fetch(url);
        let parsedData=await data.json()
        console.log(parsedData);
        this.setState({articles:parsedData.articles,totalArticles:parsedData.tot})
      }

      handlePrevClick = async()=>{
        console.log("prev");
        let url=`https://newsapi.org/v2/top-headlines?country=us&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page=${this.state.page-1}&pageSize=20`;
        let data= await fetch(url);
        let parsedData=await data.json()
        console.log(parsedData);
        this.setState({
          page: this.state.page-1,
          articles:parsedData.articles       
         })

      }
        handleNextClick =  async()=>{
        console.log("next");
        let url=`https://newsapi.org/v2/top-headlines?country=us&apiKey=e0bf6b99ba274e929b45c898fa8738cc&page=${this.state.page+1}&pageSize=20`;
        let data= await fetch(url);
        let parsedData=await data.json()
        console.log(parsedData);
        //zthis.setState({articles:parsedData.articles})

        this.setState({
          page: this.state.page+1,
          articles:parsedData.articles
        })
      }
  render() {
    return (
      <div className="container my-3">
        <h2> Newsmonkey -Top Headlines</h2>
        <div className="row">
          { 
          
          this.state.articles.map((element)=>{
             return <div className="col-md-4" key={element.url}>
               <NewsItem  title={element?element.title:""} description={element.description?element.description:""} imageurl={element.urlToImage} newsUrl={element.url}/>
          </div>

          
          // <div className="col-md-4"> <NewsItem key={element.url} title={element.title} description={element.description} imageurl={element.urlToImage} newsUrl="TODO"/>
          // </div> 
        })}
        
        
      
        {/* <div className="col-md-4">
        <NewsItem title="mytitle" description="mydesc" imageurl="https://encrypted-tbn1.gstatic.com/licensed-image?q=tbn:ANd9GcR6AK1OtJ2FXnHR6omrAJwzJUpDnlRN4K-L3NfsTyFLYE2M4MFb26tkd0lxmNiNcEtINJw_Bjvc3RrQysQ"/>
        </div>
        <div className="col-md-4">
        <NewsItem title="mytitle" description="mydesc" imageurl="https://encrypted-tbn1.gstatic.com/licensed-image?q=tbn:ANd9GcR6AK1OtJ2FXnHR6omrAJwzJUpDnlRN4K-L3NfsTyFLYE2M4MFb26tkd0lxmNiNcEtINJw_Bjvc3RrQysQ"/>
        </div> */}
        {/* <div className="col-md-4">
        <NewsItem title="mytitle" description="mydesc"/>
        </div> */}
        
        <div className="container d-flex justify-content-between">
        <button  disabled={this.state.page<=1}type="button" class="btn btn-dark" onClick={this.handlePrevClick}> &larr; Previous</button>
        <button type="button" class="btn btn-dark" onClick={this.handleNextClick}> Next &rarr;</button>
        </div>
        </div>
       
      </div>
    )
  }
}

export default news
